#include <utility>

// SolePtr<T>: one owner, or none.
template <typename T>
class SolePtr {
public:
    SolePtr() = default;
    explicit SolePtr(T* p) : ptr_(p) {}
    ~SolePtr() { delete ptr_; }

    SolePtr(const SolePtr&) = delete;
    SolePtr& operator=(const SolePtr&) = delete;
    SolePtr(SolePtr&& other) noexcept : ptr_(other.release()) {}
    SolePtr& operator=(SolePtr&& other) noexcept {
        T* taken = other.release();   // take the source first: the old object may own it
        T* old = ptr_;
        ptr_ = taken;
        delete old;
        return *this;
    }

    T* release() {
        T* p = ptr_;
        ptr_ = nullptr;
        return p;
    }
    T* get() const { return ptr_; }
    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }

private:
    T* ptr_ = nullptr;
};

// CountedPtr<T>: shared owners and one count on the heap.
template <typename T>
class CountedPtr {
public:
    CountedPtr() = default;
    explicit CountedPtr(T* p) : ptr_(p), count_(p ? new long(1) : nullptr) {}
    CountedPtr(SolePtr<T>&& s) : CountedPtr(s.release()) {}

    CountedPtr(const CountedPtr& other) : ptr_(other.ptr_), count_(other.count_) {
        if (count_) ++*count_;
    }
    CountedPtr(CountedPtr&& other) noexcept : ptr_(other.ptr_), count_(other.count_) {
        other.ptr_ = nullptr;
        other.count_ = nullptr;
    }
    // Build the new share first, then swap: the old share is dropped last, by the temporary.
    CountedPtr& operator=(const CountedPtr& other) {
        CountedPtr copy(other);
        swap(copy);
        return *this;
    }
    CountedPtr& operator=(CountedPtr&& other) noexcept {
        CountedPtr taken(std::move(other));
        swap(taken);
        return *this;
    }
    ~CountedPtr() {
        if (count_ && --*count_ == 0) {
            delete ptr_;
            delete count_;
        }
    }

    long use_count() const { return count_ ? *count_ : 0; }
    T* get() const { return ptr_; }
    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }

private:
    void swap(CountedPtr& other) noexcept {
        std::swap(ptr_, other.ptr_);
        std::swap(count_, other.count_);
    }
    T* ptr_ = nullptr;
    long* count_ = nullptr;
};
